SELECT "first_name", "last_name" FROM "players" WHERE "id" IN (SELECT "player_id" FROM (SELECT "player_id" FROM "salaries" JOIN "performances" ON "salaries"."player_id" = "performances"."player_id" AND "salaries"."year" = "performances"."year" WHERE "salaries"."year" = 2001 AND "performances"."H" > 0 ORDER BY ("salary" / "H") ASC LIMIT 10) INTERSECT SELECT "player_id" FROM (SELECT "player_id" FROM "salaries" JOIN "performances" ON "salaries"."player_id" = "performances"."player_id" AND "salaries"."year" = "performances"."year" WHERE "salaries"."year" = 2001 AND "performances"."RBI" > 0 ORDER BY ("salary" / "RBI") ASC LIMIT 10)) ORDER BY "id" ASC;
